"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["33438"],{14352(e,t,i){i.r(t),i.d(t,{metadata:()=>n,default:()=>u,frontMatter:()=>s,contentTitle:()=>r,toc:()=>h,assets:()=>l});var n=JSON.parse('{"id":"qiangguo/communismcometrue","title":"","description":"In fact, in Old Marx\'s own writings, there was never a promise that communism would inevitably be realized. Old Marx was neither God nor the Messiah, and he would never have done the sort of thing that only religious hucksters do. Some people like to connect Old Marx\'s Jewish identity with some so-called Messianic complex -- these are all baseless speculations with no meaning whatsoever.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/communismcometrue.md","sourceDirName":"qiangguo","slug":"/qiangguo/communismcometrue","permalink":"/en/qiangguo/communismcometrue","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"communismcometrue","title":"","hide_table_of_contents":true,"sidebar_label":"\\"Communism Will Inevitably Be Realized\\" Is at Least an Unrigorous Proposition"},"sidebar":"qiangguoSidebar","previous":{"title":"\u9A6C\u514B\u601D\uFF0C\u65F6\u4EE3\u7684\u7CBE\u795E\u3001\u4E16\u754C\u7684\u826F\u5FC3\uFF01\uFF08\u8FDE\u8F7D\uFF09\uFF08\u51719\u7BC7\uFF09","permalink":"/en/qiangguo/marx"},"next":{"title":"Stripping Away the Disguise of Capitalist Liberal Democracy Reveals Nothing But Naked Capitalist Dictatorship","permalink":"/en/qiangguo/dictatorshipofcapitalism"}}'),o=i(74848),a=i(28453);let s={id:"communismcometrue",title:"",hide_table_of_contents:!0,sidebar_label:'"Communism Will Inevitably Be Realized" Is at Least an Unrigorous Proposition'},r='"Communism Will Inevitably Be Realized" Is at the Very Least an Unrigorous Proposition!',l={},h=[];function m(e){let t={h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"communism-will-inevitably-be-realized-is-at-the-very-least-an-unrigorous-proposition",children:'"Communism Will Inevitably Be Realized" Is at the Very Least an Unrigorous Proposition!'})}),"\n",(0,o.jsx)(t.p,{children:"In fact, in Old Marx's own writings, there was never a promise that communism would inevitably be realized. Old Marx was neither God nor the Messiah, and he would never have done the sort of thing that only religious hucksters do. Some people like to connect Old Marx's Jewish identity with some so-called Messianic complex -- these are all baseless speculations with no meaning whatsoever."}),"\n",(0,o.jsx)(t.p,{children:"Old Marx merely pointed out a possibility. What was more important to him was identifying the ailments of contemporary society and its possible modes of destruction. Even the claim that Old Marx deduced the demise of capitalism from the premise that all things must perish is a misunderstanding of him, because Old Marx never believed in a priori premises. He did not even believe in Kant's, let alone accept such premises himself. Communism is not an a priori goal, much less an a priori premise -- Old Marx understood this better than anyone."}),"\n",(0,o.jsx)(t.p,{children:'Nobody knows when "communism will inevitably be realized" became a so-called certainty. In fact, a very simple example can refute this proposition: "the realization of communism" presupposes the existence of human beings. Without humans, what communism is there to speak of? The existence of humanity has no inherent inevitability whatsoever. A nuclear war, for instance, or a catastrophe beyond what current science can predict, would be sufficient to annihilate the human race. Where are the dinosaurs now? Who can guarantee that humanity will not share the fate of the dinosaurs? There is no God -- we are all merely humans who turn to ash within a hundred years or so. Therefore no one can guarantee anything, and even if someone did, it would be nothing but an empty check! Because when the time comes to cash it, the guarantor will be gone, and perhaps humanity itself will no longer exist. So what exactly is "inevitable" about anything?'}),"\n",(0,o.jsx)(t.p,{children:'Therefore, if "communism will inevitably be realized" is to become a rigorous proposition, at minimum it must be prefaced with the premise that humanity continues to exist, and furthermore with the premise that humanity will not perish before so-called communism arrives. In other words, if humanity goes extinct before so-called capitalism has even perished, then the whole thing becomes nothing but a joke. So never mind whether communism will happen or not -- first ensure that people alive today live well. Without the people of today, talking about communism is utterly meaningless!'})]})}function u(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(m,{...e})}):m(e)}},28453(e,t,i){i.d(t,{R:()=>s,x:()=>r});var n=i(96540);let o={},a=n.createContext(o);function s(e){let t=n.useContext(a);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),n.createElement(a.Provider,{value:t},e.children)}}}]);